import{_ as t}from"./chunks/calendar-plus.DIshg-3Q.js";import{_ as a,o as r,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Calendar +","description":"Independent calendar widget set with automatic discovery, upcoming events and a details popup.","frontmatter":{"title":"Calendar +","description":"Independent calendar widget set with automatic discovery, upcoming events and a details popup."},"headers":[],"relativePath":"en/projects/grafik-visual-studio/calendar-plus.md","filePath":"en/projects/grafik-visual-studio/calendar-plus.md","lastUpdated":1793125707000}'),o={name:"en/projects/grafik-visual-studio/calendar-plus.md"};function i(d,e,l,g,c,p){return r(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="calendar" tabindex="-1">Calendar + <a class="header-anchor" href="#calendar" aria-label="Permalink to &quot;Calendar +&quot;">​</a></h1><p><strong>Calendar + 0.1.1</strong> is an independent external widget set by <strong>rockbaer2007</strong> for <strong>Grafik Visual Studio 0.1.267 or newer</strong>. It discovers all available Home Assistant calendars automatically and displays upcoming events as a compact card or expanded list. All calendars are enabled initially.</p><p>Runtime with sample data:</p><p><img src="'+t+'" alt="Calendar + with colored date tiles, day groups and upcoming events"></p><h2 id="original-project" tabindex="-1">Original project <a class="header-anchor" href="#original-project" aria-label="Permalink to &quot;Original project&quot;">​</a></h2><p>Inspired by <strong><a href="https://github.com/xBourner/calendar-card-plus" target="_blank" rel="noreferrer">calendar-card-plus by xBourner</a></strong>, published under the <a href="https://github.com/xBourner/calendar-card-plus/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT license</a>, Copyright (c) 2026 xBourner. Calendar + uses an independent Studio implementation and its own palette icon. No original source code or images are included. This set is independent of Industrial and the separately usable original Lovelace card.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li>Update Studio to <strong>0.1.267 or newer</strong>.</li><li><a href="https://raw.githubusercontent.com/rockbaer2007/ugso-ha-mqtt-addons/master/ha_grafik_visual_studio/packages/calendar-plus/ugso.calendar-plus.wg" target="_blank" rel="noreferrer">Download ugso.calendar-plus.wg</a>.</li><li>Install under <strong>Settings → Widget packages → Local</strong>.</li><li>Drag <strong>Calendar + → Calendar +</strong> from the palette onto the page.</li></ol><p>The package contains declarative data, an icon, instructions and the MIT license. Studio provides the fixed <code>calendar-plus</code> host renderer; there are no executable package scripts. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/calendar-plus" target="_blank" rel="noreferrer">Source and package instructions</a>.</p><h2 id="my-calendars" tabindex="-1">My calendars <a class="header-anchor" href="#my-calendars" aria-label="Permalink to &quot;My calendars&quot;">​</a></h2><p>All available <code>calendar.*</code> entities are discovered, including calendars without a registry entry. Registry entries disabled in Home Assistant are omitted. <strong>My calendars</strong> provides a section for each calendar with its entity ID, a <strong>top-right checkbox to show/hide</strong>, <strong>Color</strong> and optional <strong>Background color</strong>. There is no manual calendar count.</p><p>From Studio <strong>0.1.268</strong>, the section is named <strong>Tile settings</strong> (previously “Colors”). <strong>Calendar tile size</strong> offers four fixed sizes: <strong>Extra small 36 × 44 px</strong>, <strong>Small 44 × 52 px</strong>, <strong>Medium 58 × 64 px</strong> (default) and <strong>Large 76 × 82 px</strong>. Applies to the event list and details popup. Header text stays at least <strong>12 px</strong>, day digits at least <strong>24 px</strong>, independently of the general font size. Narrow widgets keep the selected size. Existing 0.1.0/0.1.1 installations receive the settings with the Studio update; reinstalling the package is unnecessary. The calendar has no data-flow settings or input/output points.</p><p>Visibility and colors are saved by entity ID. Newly discovered calendars are enabled automatically; hidden calendars are not queried for events. The number of discovered calendars is unlimited. Requests use batches of at most 20 calendars through the Home Assistant interface.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>From Studio <strong>0.1.270</strong>, <strong>Tile settings → Tile corner radius (px)</strong> controls all four date-tile corners together: <strong>0 = square</strong>, default <strong>10 px</strong>, maximum <strong>100 px</strong>. Also applies to the details popup.</p><p>Calendar and Printer now expose all CSS sections under <strong>Properties → WIDGET</strong>: <strong>General CSS</strong>, <strong>CSS Font &amp; Text</strong>, <strong>CSS background</strong>, <strong>CSS borders</strong>, and <strong>CSS shadow and spacing</strong>. The four additional groups start disabled to preserve the existing appearance. Enable a group&#39;s checkbox to configure fonts, background/image, borders, radius, shadows and spacing. Values style the actual card surface; the outer radius under <strong>CSS borders</strong> is separate from the small date-tile radius. Semantic colors such as calendar and printer status colors remain separate settings. <strong>General CSS</strong> stays active for position, size and visibility. No new package required.</p><p>From Studio <strong>0.1.269</strong>, <strong>Tile settings</strong> also provides <strong>Top font size</strong> (month/weekday, up to 72 px) and <strong>Bottom font size</strong> (day number, up to 120 px). <strong>0 = automatic</strong> uses the selected tile size defaults. Custom values may be smaller and are constrained when space is insufficient. Requested values stay saved, allowing larger tiles to use larger fonts again.</p><p>The colored header grows with its text and a little padding, up to <strong>one third of the tile height</strong>. The day number fits the remaining area. Tile dimensions stay unchanged. Settings apply to both event list and details popup; no new widget package is required.</p><table tabindex="0"><thead><tr><th>Section</th><th>Setting</th></tr></thead><tbody><tr><td>Configuration</td><td>Heading, <strong>1–90 days</strong> lookahead, <strong>1–20</strong> visible events, expand events, details popup, dividers.</td></tr><tr><td>Grouping</td><td>By day, additionally by calendar; optionally show empty days.</td></tr><tr><td>Upcoming events</td><td>Show/hide relative labels such as “Tomorrow”, “In 2 days” or “In progress”.</td></tr><tr><td>Text &amp; visibility</td><td>Individually show/hide calendar name, date, location, duration, time and weekday; full/short weekday; swap month and weekday in the date tile.</td></tr><tr><td>Tile settings</td><td>Four tile sizes, automatic browser theme or fixed light/dark mode, accent color and <strong>10–24 px</strong> font size. Per-calendar colors and backgrounds are configured separately.</td></tr><tr><td>Size</td><td>Default <strong>480 × 460 px</strong>, minimum <strong>260 × 180 px</strong>; the event list scrolls when space is limited.</td></tr></tbody></table><p>With the expanded list disabled, one event remains visible. In runtime, clicking an event or <strong>All events</strong> opens the details popup with up to 100 events. Full dates, location and description appear when available. Content is rendered as plain text. <strong>Close</strong>, Escape or clicking outside closes the popup.</p><h2 id="data-and-refresh" tabindex="-1">Data and refresh <a class="header-anchor" href="#data-and-refresh" aria-label="Permalink to &quot;Data and refresh&quot;">​</a></h2><p>Editor and runtime read events through <code>calendar.get_events</code>. All-day events respect the exclusive end date; expired events are removed. <strong>Configuration → Refresh automatically (60 s)</strong> disables or enables periodic refresh (default: enabled). Runtime page entry loads fresh calendars and events even with automatic refresh disabled. <strong>↻</strong> still refreshes manually. Calendar discovery is refreshed as well.</p><p>Refresh replaces only event lists and preserves scroll positions and an open details popup. Unrelated live widget state changes do not rebuild an unchanged calendar. Leaving the page stops its refresh timer.</p><p>“No calendars found”, “All calendars hidden”, “No upcoming events” and a loading error are separate states. An error is not presented as an empty calendar. Language follows the Studio <strong>DE/EN</strong> setting automatically; custom headings and event content stay unchanged.</p><h2 id="scope-of-this-version" tabindex="-1">Scope of this version <a class="header-anchor" href="#scope-of-this-version" aria-label="Permalink to &quot;Scope of this version&quot;">​</a></h2><p>This version reads events. <strong>New event</strong>, editing and deleting are not included yet. Calendars must be available in Home Assistant; there is no direct ICS/Google sign-in. Installing the original card through HACS is not required.</p>',26)])])}const f=a(o,[["render",i]]);export{m as __pageData,f as default};
